using Servicio.RetazoMarket.Business.DTOs.Material;
namespace Servicio.RetazoMarket.Business.Validators;
public static class MaterialValidator { public static IReadOnlyCollection<string> Validar(CrearMaterialRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_categoria,r.mat_nombre,r.unidad_medida,r.mat_estado).ToList();if(r.stock_actual<0)e.Add("El stock no puede ser negativo.");if(decimal.Round(r.stock_actual,3)!=r.stock_actual)e.Add("El stock admite máximo tres decimales.");return e;} public static IReadOnlyCollection<string> Validar(ActualizarMaterialRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_categoria,r.mat_nombre,r.unidad_medida,r.mat_estado).ToList();if(r.id_material<=0)e.Insert(0,"El id del material es inválido.");return e;} public static IReadOnlyCollection<string> ValidarFiltro(MaterialFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");if(r.stock_minimo<0||r.stock_maximo<0)e.Add("Los límites de stock no pueden ser negativos.");if(r.stock_minimo>r.stock_maximo)e.Add("El stock mínimo no puede superar al máximo.");return e;} private static IReadOnlyCollection<string> Campos(int cat,string? n,string? u,string? s){var e=new List<string>();if(cat<=0)e.Add("La categoría es obligatoria.");if(string.IsNullOrWhiteSpace(n)||n.Trim().Length>100)e.Add("El nombre es obligatorio y admite hasta 100 caracteres.");if(string.IsNullOrWhiteSpace(u)||u.Trim().Length>50)e.Add("La unidad de medida es obligatoria y admite hasta 50 caracteres.");if(s?.Trim().ToUpperInvariant() is not("ACT" or "INA"))e.Add("El estado debe ser ACT o INA.");return e;} }
